// Generated stand-in for an ACP agent (`agy acp`, `gemini --acp`): newline-delimited JSON-RPC 2.0 over stdio.
// It never contacts Google, never reads credentials and records what it receives in FAKE_ACP_LOG.
import { appendFileSync, writeFileSync } from "node:fs";
import { spawn } from "node:child_process";
import { createInterface } from "node:readline";
import { join } from "node:path";

const log = process.env.FAKE_ACP_LOG;
const record = (entry) => { if (log) appendFileSync(log, `${JSON.stringify(entry)}\n`); };
record({ started: true, args: process.argv.slice(2), ambient: ["GEMINI_API_KEY", "GOOGLE_API_KEY", "GOOGLE_APPLICATION_CREDENTIALS"].filter((name) => process.env[name] !== undefined),
  noBrowser: process.env.NO_BROWSER ?? null });
const write = (message) => process.stdout.write(`${JSON.stringify({ jsonrpc: "2.0", ...message })}\n`);
const waiters = new Map();
let counter = 0, session = null, cwd = null, cancel = null;
const ask = (method, params) => new Promise((resolve) => { const id = `agent-${++counter}`; waiters.set(id, resolve); write({ id, method, params }); });
const update = (value) => write({ method: "session/update", params: { sessionId: session, update: value } });
const say = (text) => update({ sessionUpdate: "agent_message_chunk", content: { type: "text", text } });
const options = [{ optionId: "yes-once", name: "Allow", kind: "allow_once" }, { optionId: "yes-always", name: "Always", kind: "allow_always" }, { optionId: "no", name: "Reject", kind: "reject_once" }];
const models = { configOptions: [{ id: "model", name: "Model", category: "model", type: "select", currentValue: "gemini-generated-pro",
  options: [{ value: "gemini-generated-pro", name: "Generated Pro" }, { group: "more", name: "More", options: [{ value: "generated/flash", name: "Generated Flash" }] }] }] };

async function prompt(text) {
  if (text.includes("generated acp write")) {
    update({ sessionUpdate: "agent_thought_chunk", content: { type: "text", text: "Generated plan." } });
    const path = join(cwd, "acp-output.txt");
    update({ sessionUpdate: "tool_call", toolCallId: "w1", title: "Write acp-output.txt", kind: "edit", status: "pending", locations: [{ path }], rawInput: { path } });
    const answer = await ask("session/request_permission", { sessionId: session, toolCall: { toolCallId: "w1", title: "Write acp-output.txt", kind: "edit", locations: [{ path }] }, options });
    record({ permission: answer });
    if (answer.outcome?.optionId === "yes-once") {
      writeFileSync(path, "generated by fake acp\n");
      update({ sessionUpdate: "tool_call_update", toolCallId: "w1", status: "completed", content: [{ type: "diff", path, oldText: null, newText: "generated by fake acp\n" }] });
    } else update({ sessionUpdate: "tool_call_update", toolCallId: "w1", status: "failed", content: [{ type: "content", content: { type: "text", text: "Rejected." } }] });
    say("Generated ACP write complete.");
    update({ sessionUpdate: "usage_update", used: 150, size: 1000000, cost: { amount: 0.0125, currency: "USD" } });
    return { stopReason: "end_turn", usage: { inputTokens: 100, outputTokens: 40, cachedReadTokens: 10, totalTokens: 150 } };
  }
  if (text.includes("generated acp read")) {
    update({ sessionUpdate: "tool_call", toolCallId: "r1", title: "Read fixture.txt", kind: "read", status: "completed", locations: [{ path: join(cwd, "fixture.txt") }],
      content: [{ type: "content", content: { type: "text", text: "fixture contents" } }] });
    say("Generated ACP read complete.");
    return { stopReason: "end_turn" };
  }
  if (text.includes("generated acp command")) {
    const answer = await ask("session/request_permission", { sessionId: session, toolCall: { toolCallId: "c1", title: "npm test", kind: "execute", rawInput: { command: "npm test" } }, options });
    record({ permission: answer });
    update({ sessionUpdate: "tool_call_update", toolCallId: "c1", status: "failed", content: [{ type: "content", content: { type: "text", text: "Rejected by the user." } }] });
    say("Generated ACP command was declined.");
    return { stopReason: "end_turn" };
  }
  if (text.includes("generated acp rogue")) {
    update({ sessionUpdate: "tool_call", toolCallId: "x1", title: "rm generated", kind: "execute", status: "completed", rawInput: { command: "rm generated" } });
    say("Generated ACP rogue complete.");
    return { stopReason: "end_turn" };
  }
  if (text.includes("generated acp hang")) {
    const orphan = spawn("sleep", ["60"], { stdio: "ignore" });
    record({ orphan: orphan.pid });
    say("Generated ACP is working.");
    await new Promise((resolve) => { cancel = resolve; });
    return { stopReason: "cancelled" };
  }
  say(`Generated ACP echo: ${text.slice(-80)}`);
  return { stopReason: "end_turn" };
}

createInterface({ input: process.stdin }).on("line", async (line) => {
  if (!line.trim()) return;
  const message = JSON.parse(line);
  if (message.id !== undefined && !message.method) { waiters.get(message.id)?.(message.result ?? {}); waiters.delete(message.id); return; }
  record({ method: message.method, params: message.params, jsonrpc: message.jsonrpc });
  const reply = (result) => write({ id: message.id, result }), fail = (code, text) => write({ id: message.id, error: { code, message: text } });
  switch (message.method) {
    case "initialize":
      return reply({ protocolVersion: 1, agentCapabilities: { loadSession: true }, agentInfo: { name: "Generated ACP", version: process.env.FAKE_ACP_VERSION ?? "1.6.0" },
        authMethods: [{ id: "oauth-personal", name: "Generated Google sign-in" }] });
    case "session/new":
      if (process.env.FAKE_ACP_AUTH === "none") return fail(-32000, "Authentication required");
      cwd = message.params.cwd; session = `generated-acp-${Date.now().toString(36)}`;
      return reply({ sessionId: session, ...models });
    case "session/load":
      cwd = message.params.cwd; session = message.params.sessionId;
      say("Replayed earlier history that Moguri must ignore.");
      return reply({ ...models });
    case "session/set_model": return reply({});
    case "session/prompt": {
      const text = (message.params.prompt ?? []).map((block) => block.text ?? "").join("");
      return reply(await prompt(text));
    }
    case "session/cancel": cancel?.(); return;
    default: if (message.id !== undefined) fail(-32601, `Generated agent does not serve ${message.method}.`);
  }
});
